{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Fluconazole absolute oral bioavailability was over 90% versus intravenous administration in normal volunteers, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C70"],
      "claim": "Dapagliflozin absolute oral bioavailability was 78% (90% CI 73-83) after a 10 mg oral dose in healthy subjects, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Mosliciguat absolute oral bioavailability was 23.1% in healthy male volunteers after a 1000 µg oral solution versus 100 µg IV, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All ten evidence molecules, weighted by high assay-transfer scores and direct absolute bioavailability measurements, support F >= 20%; the lowest numeric absolute values remain above the threshold.",
  "evidence_gaps": [
    "Some ziprasidone records are food-dependent (30% fasted vs ~60% fed), but both are above the threshold.",
    "Halofantrine has qualitative 'low bioavailability' reports, but the numeric absolute estimate is ~30%, above the threshold.",
    "Indomethacin has low values in infant/preterm populations, while adult absolute values are high; population match to the target is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

